{
  "/workspace/runtime/local/workspace/run-ceobench/observe.py": {
    "type": "add",
    "content": "import json
import novamind_api as nm

day = nm.vars.current_day
queries = {
    'cash': 'SELECT SUM(amount) AS cash FROM ledger',
    'finance': f'SELECT category,ROUND(SUM(amount),2) AS amount FROM ledger WHERE day>{day-7} GROUP BY category',
    'segments': "SELECT c.group_id,s.plan,COUNT(*) AS subscribers,SUM(s.seat_count) AS seats,ROUND(SUM(s.effective_price*s.seat_count),2) AS mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan",
    'conversion': f"SELECT c.group_id,s.status,COUNT(*) AS n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.created_day>{day-7} GROUP BY c.group_id,s.status",
    'ads': f'SELECT channel_id,group_id,SUM(leads_generated) AS leads,SUM(spend) AS spend FROM ad_channel_leads WHERE day>{day-7} GROUP BY channel_id,group_id',
    'service': f'SELECT MAX(total_usage_units) AS peak_usage,MAX(downtime_minutes) AS downtime FROM service_day WHERE day>{day-7}',
    'issues': "SELECT group_id,COUNT(*) AS n,MAX(days_open) AS oldest FROM issues WHERE status='open' GROUP BY group_id",
    'threads': "SELECT e.customer_id,c.group_id,e.thread_id,e.day,e.thread_type,e.seat_count,e.message_text,e.offer_json FROM enterprise_turns e JOIN customers c ON c.customer_id=e.customer_id WHERE e.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND e.closed=0 AND e.sender='customer'",
}
out = {'day':day}
for name,sql in queries.items():
    out[name] = nm.query(sql)['rows']
print(json.dumps(out,indent=2))
"
  }
}

