{
  "/workspace/runtime/local/workspace/run-ceobench/deals.py": {
    "type": "add",
    "content": "import json
import novamind_api as nm

rows = nm.query("SELECT e.customer_id,c.group_id,e.sender,e.message_text,e.offer_json FROM enterprise_turns e JOIN customers c ON c.customer_id=e.customer_id WHERE e.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND e.closed=0 AND e.sender!='agent' AND e.customer_id IN (SELECT customer_id FROM subscriptions WHERE status IN ('lead','subscribed'))")['rows']
deals=[]
for r in rows:
    offers = {'E1':[['C',18],['B',12],['A',8]],'E2':[['C',40],['B',25]],'E3':[['C',55],['B',35]]}.get(r['group_id'],[['C',25],['B',15]])
    counter=json.loads(r['offer_json'] or '{}')
    if counter.get('price'):
        offers=[['C',round(counter['price']*.98,2)]]
    deals.append([r['customer_id'],offers])
if deals:
    result=nm.enterprise.send_enterprise_deal(deals)
    print(json.dumps({'sent':len(deals),'result':result}))
else:
    print('No enterprise replies needed.')
"
  }
}

