{
  "/workspace/runtime/local/workspace/run-ceobench/brief.py": {
    "type": "add",
    "content": "import json
import novamind_api as nm

d=nm.vars.current_day
def q(sql): return nm.query(sql)['rows']
out={'day':d,'cash':q('SELECT SUM(amount) AS cash FROM ledger')[0]['cash']}
out['finance']={r['category']:round(r['amount']) for r in q(f'SELECT category,SUM(amount) AS amount FROM ledger WHERE day>{d-7} GROUP BY category')}
out['groups']=q("SELECT c.group_id,COUNT(*) AS n,SUM(s.seat_count) AS seats,ROUND(SUM(s.effective_price*s.seat_count)) AS mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id")
out['conversion']=q(f"SELECT c.group_id,COUNT(*) AS leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) AS acquired FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.created_day>{d-7} GROUP BY c.group_id")
out['ads']=q(f'SELECT channel_id,group_id,SUM(leads_generated) AS leads,SUM(spend) AS spend FROM ad_channel_leads WHERE day>{d-7} GROUP BY channel_id,group_id')
out['service']=q(f'SELECT MAX(total_usage_units) AS peak_usage,MAX(downtime_minutes) AS downtime FROM service_day WHERE day>{d-7}')
out['issues']=q("SELECT i.group_id,COUNT(*) AS n,MAX(i.days_open) AS oldest FROM issues i JOIN subscriptions s ON i.customer_id=s.customer_id WHERE i.status='open' AND s.status='subscribed' GROUP BY i.group_id")
for k,v in out.items(): print(k,json.dumps(v,separators=(',',':')))
"
  }
}

